  "Deleted user": "Usuario eliminado",
  "Deleting your account signs you out everywhere right away. After 14 days your profile, email, friends and private data are permanently deleted. Messages you sent in shared chats stay as “Deleted user”. Signing in again within 14 days cancels the deletion.": "Al eliminar tu cuenta, se cerrará tu sesión en todas partes de inmediato. Después de 14 días, tu perfil, correo, amigos y datos privados se eliminarán de forma permanente. Los mensajes que enviaste en chats compartidos se conservarán como “Usuario eliminado”. Si vuelves a iniciar sesión dentro de los 14 días, se cancelará la eliminación.",
