  "Descall was founded by Demir Sarp Kurtlar, who remains the owner and CEO.": "Descall fue fundada por Demir Sarp Kurtlar, que sigue siendo su propietario y CEO.",
  "Descall wins for squads that want DMs, groups, WebRTC voice/video, and screen share without Nitro. It is not trying to replace every public Discord server.": "Descall gana para equipos que quieren MD, grupos, voz y video WebRTC y compartir pantalla sin Nitro. No pretende reemplazar todos los servidores públicos de Discord.",
