  "Friend requests, online presence, and quick invites so your squad can jump into chat or voice.": "Solicitudes de amistad, presencia en línea e invitaciones rápidas para que tu equipo entre al chat o a la voz.",
  "Friend voice + servers → Descall. Huge community → Discord. Pure voice server → TeamSpeak. Read our compare page before you force a full migration.": "Voz con amigos + servidores → Descall. Comunidad enorme → Discord. Servidor solo de voz → TeamSpeak. Lee nuestra página de comparación antes de forzar una migración completa.",
  "Friend-group chat and voice without Nitro friction": "Chat y voz para grupos de amigos sin las trabas de Nitro",
