  "How small communities pick a Discord alternative: servers, roles, invites, voice hangouts, and when to stay on Discord.": "Cómo eligen las comunidades pequeñas una alternativa a Discord: servidores, roles, invitaciones, quedadas de voz y cuándo quedarse en Discord.",
