  "Modern": "Moderno",
  "Modern UI focused on speed, servers without endless chrome": "Interfaz moderna centrada en la velocidad, servidores sin adornos interminables",
  "Monitor mode: no DesCoin is withheld, nothing to release.": "Modo de supervisión: no se retiene DesCoin, no hay nada que liberar.",
  "Month": "Mes",
  "More": "Más",
  "More about Descall": "Más sobre Descall",
  "More options": "Más opciones",
  "More reactions": "Más reacciones",
  "Most Discord replacement attempts fail when voice feels worse. Descall invests in WebRTC calls, TURN, and screen-share presets so nightly voice stays easy.": "La mayoría de los intentos de reemplazar Discord fracasan cuando la voz se siente peor. Descall invierte en llamadas WebRTC, TURN y ajustes predefinidos para compartir pantalla, para que la voz de cada noche siga siendo fácil.",
  "Most community platforms either drown you in mega-server chrome or skip structure entirely. Descall gives you real servers with categories, text/voice/stage channels, roles, channel overrides, and ready-made community templates, so a clan, class, or creator circle can launch organized in minutes.": "La mayoría de las plataformas de comunidad te ahogan en la interfaz de los megaservidores o se saltan la estructura por completo. Descall te da servidores reales con categorías, canales de texto/voz/escenario, roles, excepciones por canal y plantillas de comunidad listas, para que un clan, una clase o el círculo de un creador arranquen organizados en minutos.",
  "Most friend groups feel settled within two weeks of moving evening voice.": "La mayoría de los grupos de amigos se sienten instalados en las dos semanas siguientes a mudar la voz de las noches.",
  "Most groups dual-stack for a month, then realize 90% of pings happen on Descall. That’s a healthy Discord replacement path, no big-bang migration required.": "La mayoría de los grupos usan ambas apps durante un mes y luego se dan cuenta de que el 90 % de las menciones ocurren en Descall. Es un camino sano para reemplazar Discord, sin necesidad de una migración de golpe.",
  "Most groups want both. Descall pairs DMs and servers with the same voice stack so you are not juggling two apps.": "La mayoría de los grupos quieren ambas cosas. Descall combina MD y servidores con el mismo sistema de voz para que no tengas que hacer malabares con dos apps.",
