  "People": "Personas",
  "People in voice": "Personas en voz",
  "People saying “apps like Discord” usually want chat + persistent groups + voice. Some also want screen share. Descall covers that core. It does not try to clone every Discord bot and Stage feature, and that focus is the product.": "Quienes dicen “apps como Discord” suelen querer chat + grupos permanentes + voz. Algunos también quieren compartir pantalla. Descall cubre esa base. No intenta clonar cada bot ni la función de Escenarios de Discord, y ese enfoque es el producto.",
  "People you may know, ranked by mutual friends and shared groups.": "Personas que quizá conozcas, ordenadas por amigos y grupos en común.",
  "Performance": "Rendimiento",
  "Performance Impact": "Impacto en el rendimiento",
