  "PiP / minimize-friendly call UX": "Llamadas con PiP y fáciles de minimizar",
  "Pick Descall for nightly friend voice and servers without Nitro. Keep Discord if you still depend on a large bot marketplace or huge public servers.": "Elige Descall para la voz de cada noche con amigos y servidores sin Nitro. Quédate con Discord si todavía dependes de un gran mercado de bots o de servidores públicos enormes.",
  "Pick Descall when your group wants a lighter Discord alternative for chat, voice, and screen share. Keep Discord when you still run large public communities and bots.": "Elige Descall cuando tu grupo quiera una alternativa más ligera a Discord para chat, voz y compartir pantalla. Quédate con Discord cuando todavía gestiones grandes comunidades públicas y bots.",
  "Pick Gaming, Friends, or Community templates so roles and staff rooms appear ready. Invite codes replace Discord’s invite links.": "Elige las plantillas Gaming, Amigos o Comunidad para que los roles y las salas del staff aparezcan listos. Los códigos de invitación reemplazan a los enlaces de invitación de Discord.",
  "Pick a DM or group, then start a voice or video call": "Elige un MD o grupo y luego inicia una llamada de voz o videollamada",
  "Pick a GIF": "Elige un GIF",
  "Pick a friend, start a DM, or create a group, Descall keeps it light.": "Elige a un amigo, inicia un MD o crea un grupo. Descall lo mantiene simple.",
