  "Themes": "Temas",
  "Themes, frames, and effects via DesCoin. Core chat, servers, and calls stay free forever.": "Temas, marcos y efectos con DesCoin. El chat, los servidores y las llamadas básicos seguirán siendo gratis para siempre.",
  "Then enable notifications for calls and DMs.": "Luego activa las notificaciones para llamadas y MD.",
  "There is no bulk Discord history importer today. Pin key links, rebuild channels, and start fresh voice nights on Descall.": "Por ahora no hay una herramienta para importar en bloque el historial de Discord. Fija los enlaces clave, reconstruye los canales y empieza de cero las noches de voz en Descall.",
  "There is no verified email. Verify your current address first.": "No hay ningún correo verificado. Verifica primero tu dirección actual.",
  "They answered on a locked iPhone but couldn't join in time. Try calling again.": "Respondió en un iPhone bloqueado, pero no pudo unirse a tiempo. Intenta llamar de nuevo.",
  "This account doesn’t have an email address, so we can’t send a reset code. Contact support and we’ll help you recover access.": "Esta cuenta no tiene una dirección de correo, así que no podemos enviar un código de restablecimiento. Contacta con soporte y te ayudaremos a recuperar el acceso.",
  "This account has no email on file. Contact support@descall.com to recover access.": "Esta cuenta no tiene un correo registrado. Escribe a support@descall.com para recuperar el acceso.",
  "This account has no email on file. Contact {support} to recover access.": "Esta cuenta no tiene ningún correo registrado. Contacta con {support} para recuperar el acceso.",
