  "This account has no password. Enter the code sent to your saved email, then you can add the new address.": "Esta cuenta no tiene contraseña. Escribe el código enviado a tu correo guardado y luego podrás agregar la nueva dirección.",
  "This account has no recorded device or IP address.": "Esta cuenta no tiene ningún dispositivo ni dirección IP registrados.",
