  "Write your must-haves (voice, servers, mobile). Trial with your real friends for seven nights. Keep the app that gets used without reminders.": "Anota lo imprescindible (voz, servidores, móvil). Pruébala con tus amigos de verdad durante siete noches. Quédate con la app que se usa sin recordatorios.",
